        "title": "Функциональные зависимости и нормальные формы",
        "body": "Функциональная зависимость X → Y означает: если две строки имеют одинаковое X, у них должно быть одинаковое Y. Например, если store_id уникален в stores, он определяет store_name. Но store_name не обязательно определяет store_id: в разных городах могут быть магазины с одинаковыми названиями.\n\nНормальные формы описывают, какие зависимости допустимы в таблице. В упрощённом практическом смысле 1НФ требует атомарных значений и отсутствия повторяющихся групп. 2НФ важна для составного ключа: неключевой столбец должен зависеть от всего ключа, а не только от его части. 3НФ устраняет транзитивные зависимости неключевых атрибутов от ключа.\n\nНе нужно механически запоминать определения без схемы. Сначала найди ключ, затем спроси: какие столбцы он определяет и не хранятся ли в этой таблице сведения о другой сущности?",
