        "title": "Числовые типы",
        "body": "Тип данных определяет, какие значения можно хранить и какие операции над ними имеют смысл. INTEGER подходит для целых чисел, BIGINT — для более широкого диапазона целых, NUMERIC — для точной десятичной арифметики, REAL и DOUBLE PRECISION — для приближённых чисел с плавающей точкой.\n\nДля денежных сумм обычно выбирают NUMERIC(p,s), где p — общее число значащих цифр, а s — число цифр после десятичной точки. Например, NUMERIC(12,2) хранит сумму с двумя знаками после запятой. DOUBLE PRECISION может давать небольшие погрешности округления, потому что хранит двоичное приближение.\n\nВыбирай тип по смыслу и диапазону, а не по принципу «самый большой на всякий случай». Для идентификатора, который никогда не участвует в дробной арифметике, целочисленный тип обычно уместнее NUMERIC.",
        "example": "CREATE TABLE payments (\n  payment_id BIGINT PRIMARY KEY,\n  amount NUMERIC(12, 2) NOT NULL,\n  tax_rate NUMERIC(5, 4)\n);",
        "note": "NUMERIC(12,2) допускает до 10 цифр до точки и 2 после неё. Не путай точный NUMERIC с приближённым DOUBLE PRECISION.",
