        "title": "BOOLEAN, UUID и специальные типы",
        "body": "BOOLEAN хранит логические значения TRUE и FALSE, а также может содержать NULL, если столбец не объявлен NOT NULL. Это означает, что логический столбец тоже может иметь неизвестное состояние.\n\nUUID — 128-битный идентификатор, удобный для распределённых систем и генерации ID без единого счётчика. Он длиннее BIGINT и обычно хуже читается человеком, зато вероятность случайного совпадения крайне мала при корректной генерации.\n\nВ PostgreSQL есть и специальные типы: JSONB для структурированных документов, массивы для наборов значений одного типа, диапазоны для интервалов. Используй их, когда они отражают реальную модель данных, а не чтобы избежать проектирования таблиц.",
