        "body": "IN проверяет, входит ли значение в перечисленный набор. Это удобная запись нескольких сравнений через OR. BETWEEN проверяет попадание в диапазон и включает обе границы. Для исключения набора используют NOT IN, но с ним нужно осторожно обращаться при наличии NULL в списке.\n\nДля дат BETWEEN '2026-01-01' AND '2026-01-31' включит обе даты. Если столбец имеет тип timestamp, верхняя граница '2026-01-31' означает полночь в начале этого дня, а не весь день 31 января. Для временных интервалов часто надёжнее писать >= начала и < начала следующего периода.\n\nВыбирай конструкцию по смыслу: IN для списка конкретных значений, BETWEEN для закрытого диапазона, а полуоткрытые интервалы особенно удобны для временных меток.",
