        "title": "LIMIT и OFFSET",
        "body": "LIMIT ограничивает количество строк результата, а OFFSET пропускает указанное число строк. Это простой способ получить первую страницу или посмотреть небольшой фрагмент таблицы.\n\nНо LIMIT без ORDER BY не определяет, какие именно строки попадут в результат. Даже с сортировкой OFFSET становится дорогим на глубоких страницах: серверу приходится пройти и пропустить всё больше строк.\n\nДля интерфейсов с большим объёмом данных часто используют keyset pagination: вместо пропуска N строк передают значение последней строки предыдущей страницы и выбирают следующие записи по стабильному ключу.",
