        "body": "GROUPING SETS, ROLLUP и CUBE строят несколько уровней группировки в одном запросе. Например, можно получить выручку по городу и статусу, отдельно итоги по городу и общий итог.\n\nROLLUP(city, status) создаёт иерархические подытоги: пары город + статус, итоги по городу и общий итог. CUBE строит все комбинации подмножеств столбцов, что может резко увеличить число групп. GROUPING SETS позволяет перечислить точные нужные наборы группировки.\n\nВ строках подытогов столбцы, которые не участвуют в конкретной группе, становятся NULL. Чтобы отличить такой NULL от настоящего NULL в исходных данных, используй GROUPING().",
