        "body": "Кардинальность описывает, сколько строк одной таблицы может соответствовать строке другой: один-к-одному, один-ко-многим или многие-ко-многим. Даже если ожидается один-к-одному, проверь уникальность ключа на стороне справочника.\n\nЕсли справочник содержит несколько строк с одним customer_id, один заказ соединится со всеми этими строками и размножится. Это увеличит COUNT(*) и может завысить SUM. Проблема часто не в синтаксисе JOIN, а в нарушенном предположении о кардинальности.\n\nПроверить уникальность можно отдельным запросом GROUP BY ... HAVING COUNT(*) > 1. Если дубли допустимы по смыслу, нужно уточнить правило выбора нужной записи, например актуальную версию через ROW_NUMBER.",
