        "title": "Anti join и semi join через EXISTS",
        "body": "Semi join нужен, когда требуется оставить строки левой таблицы, для которых существует хотя бы одно совпадение справа, но данные правой таблицы не нужны. В SQL это удобно выражать через EXISTS.\n\nAnti join делает обратное: оставляет строки, для которых совпадений нет. Обычно используют NOT EXISTS. Это читается как вопрос существования, а не как необходимость присоединить все совпавшие строки.\n\nEXISTS прекращает логическую проверку на факте существования подходящей строки. В отличие от обычного JOIN, он не размножает левую строку, если справа найдено несколько совпадений. Для anti join NOT EXISTS обычно безопаснее NOT IN, если подзапрос может вернуть NULL.",
