        "title": "ROW_NUMBER, RANK и DENSE_RANK",
        "body": "ROW_NUMBER присваивает строкам последовательные номера внутри окна. RANK присваивает одинаковый ранг равным значениям и оставляет пропуски после ничьей. DENSE_RANK тоже присваивает одинаковый ранг равным значениям, но не пропускает следующий номер.\n\nНапример, если оценки равны 100, 90, 90, 80, ROW_NUMBER даст 1, 2, 3, 4; RANK — 1, 2, 2, 4; DENSE_RANK — 1, 2, 2, 3. Порядок определяется ORDER BY внутри OVER.\n\nДля детерминированного ROW_NUMBER добавляй уникальный tie-breaker, если значения сортировки могут совпадать. Иначе две строки с одинаковым score могут получить номера в непредсказуемом порядке.",
