        "title": "LAG и LEAD",
        "body": "LAG возвращает значение из предыдущей строки окна, LEAD — из следующей. Это позволяет сравнивать текущую запись с соседней без self join.\n\nОбе функции используют ORDER BY внутри OVER, чтобы определить, какая строка считается предыдущей или следующей. Можно задать смещение и значение по умолчанию, если соседней строки нет.\n\nLAG и LEAD часто применяют для расчёта изменения метрики, времени между событиями и обнаружения переходов статусов. Важно, чтобы сортировка была однозначной: при одинаковой дате добавь уникальный идентификатор события.",
