        "title": "Оконные функции после группировки",
        "body": "Оконные функции могут применяться к уже сгруппированному результату. Сначала GROUP BY создаёт, например, одну строку на месяц, а затем SUM(...) OVER может посчитать долю месяца от общего итога или ранжировать месяцы.\n\nЭто полезно, когда нужно одновременно агрегировать исходные события и сравнить получившиеся группы между собой. Оконная функция видит уже сгруппированные строки, а не исходные заказы.\n\nПроверяй уровень данных на каждом этапе. Если агрегат внутри окна использует выражение из GROUP BY, убедись, что после группировки оно доступно и соответствует нужному зерну.",
