        "body": "Отладка сложного запроса начинается с минимального рабочего фрагмента. Сначала проверь базовую таблицу и фильтр, затем добавь один JOIN, сравни количество строк и только потом добавляй агрегацию и оконные вычисления.\n\nCTE помогают сохранять промежуточные результаты с понятными именами. Можно проверить каждый этап отдельным SELECT и увидеть, где появляются дубли, NULL или неожиданное количество строк.\n\nМеняй по одной части за раз. Если одновременно изменить JOIN, WHERE и GROUP BY, будет сложно понять, какое изменение исправило или сломало результат.",
